SELECT MIN(CASE WHEN ISFINITE(TRY_CAST("Price" AS DOUBLE)) THEN TRY_CAST("Price" AS DOUBLE) ELSE NULL END) AS result FROM (SELECT * FROM (SELECT * EXCLUDE (__mapped), __mapped."Amenities" AS "Amenities" FROM (SELECT *, STRUCT_PACK("Amenities" := NULLIF(s'Extract the amenities from the estate details.
